namespace SecretCustomer.Core.Interfaces.Services;

public interface IQRCodeService
{
    /// <summary>
    /// URL için QR kod PNG olarak üretir
    /// </summary>
    byte[] GenerateQRCode(string url, int pixelPerModule = 10);

    /// <summary>
    /// Assignment için QR kod üretir (frontend URL ile)
    /// </summary>
    byte[] GenerateAssignmentQRCode(string uniqueLink, string baseUrl);

    /// <summary>
    /// Base64 encoded QR kod string döner (HTML'de göstermek için)
    /// </summary>
    string GenerateQRCodeBase64(string url, int pixelPerModule = 10);
}

using QRCoder;
using SecretCustomer.Core.Interfaces.Services;

namespace SecretCustomer.Services.Services;

public class QRCodeService : IQRCodeService
{
    public byte[] GenerateQRCode(string url, int pixelPerModule = 10)
    {
        if (string.IsNullOrWhiteSpace(url))
            throw new ArgumentException("URL cannot be empty", nameof(url));

        using var qrGenerator = new QRCodeGenerator();
        using var qrCodeData = qrGenerator.CreateQrCode(url, QRCodeGenerator.ECCLevel.Q);
        using var qrCode = new PngByteQRCode(qrCodeData);

        return qrCode.GetGraphic(pixelPerModule);
    }

    public byte[] GenerateAssignmentQRCode(string uniqueLink, string baseUrl)
    {
        if (string.IsNullOrWhiteSpace(uniqueLink))
            throw new ArgumentException("Unique link cannot be empty", nameof(uniqueLink));

        if (string.IsNullOrWhiteSpace(baseUrl))
            throw new ArgumentException("Base URL cannot be empty", nameof(baseUrl));

        // Frontend form URL'ini oluştur
        var fullUrl = $"{baseUrl.TrimEnd('/')}/form/{uniqueLink}";

        return GenerateQRCode(fullUrl, pixelPerModule: 10);
    }

    public string GenerateQRCodeBase64(string url, int pixelPerModule = 10)
    {
        var qrBytes = GenerateQRCode(url, pixelPerModule);
        return Convert.ToBase64String(qrBytes);
    }
}

[HttpGet("{id}/qr-code")]
public async Task<IActionResult> GetQRCode(Guid id)
{
    var assignment = await _assignmentService.GetByIdAsync(id);
    if (assignment == null)
        return NotFound();

    // appsettings.json'dan base URL al veya request'ten çıkar
    var baseUrl = $"{Request.Scheme}://{Request.Host}";

    var qrBytes = _qrCodeService.GenerateAssignmentQRCode(
        assignment.UniqueLink,
        baseUrl);

    return File(qrBytes, "image/png", $"assignment-{id}-qr.png");
}

[HttpGet("{id}/qr-code/base64")]
public async Task<ActionResult<string>> GetQRCodeBase64(Guid id)
{
    var assignment = await _assignmentService.GetByIdAsync(id);
    if (assignment == null)
        return NotFound();

    var baseUrl = $"{Request.Scheme}://{Request.Host}";
    var qrBase64 = _qrCodeService.GenerateQRCodeBase64(
        $"{baseUrl}/form/{assignment.UniqueLink}");

    return Ok(new { qrCode = $"data:image/png;base64,{qrBase64}" });
}

private readonly IAssignmentService _assignmentService;
private readonly IQRCodeService _qrCodeService;  // YENİ

public AssignmentsApiController(
    IAssignmentService assignmentService,
    IQRCodeService qrCodeService)  // YENİ
{
    _assignmentService = assignmentService;
    _qrCodeService = qrCodeService;
}
